<template><div class="community-report"><button type="button" class="text-link" @click="open">Báo cáo {{ kind==='POST'?'bài viết':'bình luận' }}</button><dialog ref="dialog" class="community-dialog" :aria-labelledby="'report-title-'+kind+'-'+id" @close="closed" @cancel="cancel"><form class="community-report-form" @submit.prevent="send"><h2 :id="'report-title-'+kind+'-'+id">Báo cáo nội dung</h2><p>Quản trị viên sẽ xem xét. Một báo cáo không tự động gỡ nội dung; danh tính của bạn không được công khai cho thành viên khác.</p><label :for="'report-reason-'+kind+'-'+id">Lý do</label><select :id="'report-reason-'+kind+'-'+id" v-model="reason" :disabled="busy"><option v-for="(label,key) in reasons" :key="key" :value="key">{{ label }}</option></select><label :for="'report-description-'+kind+'-'+id">Mô tả thêm{{ reason==='OTHER'?' (bắt buộc)':'' }}</label><textarea :id="'report-description-'+kind+'-'+id" v-model="description" :required="reason==='OTHER'" maxlength="2000" rows="4" :disabled="busy"/><p v-if="error" role="alert">{{ error }}</p><p v-if="receipt" role="status">Đã tiếp nhận báo cáo #{{ receipt.id }}. Nội dung đang chờ xem xét.</p><div class="community-actions"><button type="button" class="button button-outline" :disabled="busy" autofocus @click="dialog.close()">Đóng</button><button v-if="!receipt" class="button button-primary" :disabled="busy">{{ busy?'Đang gửi…':'Gửi báo cáo' }}</button></div></form></dialog></div></template>
<script setup>
import {ref,watch} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';import {useAuth} from '../../composables/useAuth.js';const props=defineProps({kind:{type:String,required:true},id:{type:Number,required:true}}),{user}=useAuth(),dialog=ref(null),reason=ref('SPAM'),description=ref(''),busy=ref(false),error=ref(''),receipt=ref(null);let trigger;const reasons={SPAM:'Spam hoặc quảng cáo không phù hợp',HARASSMENT:'Quấy rối hoặc xúc phạm',PROHIBITED:'Nội dung không phù hợp',MISLEADING:'Thông tin gây hiểu nhầm',OTHER:'Lý do khác'};
function open(event){trigger=event.currentTarget;dialog.value.showModal();}function closed(){trigger?.focus();}function cancel(event){if(busy.value)event.preventDefault();}async function send(){if(busy.value||receipt.value)return;busy.value=true;error.value='';try{receipt.value=await request('/account/reports','POST',{targetType:'COMMUNITY_'+props.kind,targetId:props.id,reason:reason.value,description:description.value});}catch(e){error.value=e.message;}finally{busy.value=false;}}watch(()=>user.value?.id,()=>{dialog.value?.close();reason.value='SPAM';description.value='';receipt.value=null;error.value='';});
</script>
